# R186_031 — teorema T1 por normas: lambda_A(T) >= lambda_min(Son_S|P_T) - lambda_max(C_{eps_S}|P_T)
# y variante directa lambda_A(T) >= lambda_A^inf(T) - v_2/2.  Autonomo: Galerkin de r183_030_inertia
# (base (1-u^2)^2 P_j, metrica L2(h), restriccion de Tate cp) y rejillas eps(e^a) de epsg.py (R186_018,
# lambda=1, nodos a in (0, log3], 360 nodos) embebidas: RS = semilocal S={inf,2} refinada, S = semilocal memo,
# A = arquimediana.  Uso: python3 r031_t1_norms.py [M=24] [T1,T2,...]
import sys, zlib, base64, numpy as np
from numpy.polynomial import legendre as L
from scipy.special import digamma
from scipy.linalg import eigh, null_space
BLOB = ""
_g = np.frombuffer(zlib.decompress(base64.b64decode(BLOB)), dtype=np.float64).reshape(5, -1)
GA, GW, GRIDS = _g[0], _g[1], {'RS': _g[2], 'S': _g[3], 'A': _g[4]}
V2 = 2*np.log(2)/np.sqrt(2)

def build(T, M, with2, Nx=1600, smax=700.0):
    ux, wx = L.leggauss(Nx); x = T*ux; wx = T*wx
    def xi_d(u):
        V = np.array([L.legval(u, np.eye(M)[j]) for j in range(M)])
        dV = np.array([L.legval(u, L.legder(np.eye(M)[j])) for j in range(M)])
        b = (1-u**2)**2; db = -4*u*(1-u**2)
        return V*b, (dV*b+V*db)/T
    X, dX = xi_d(ux); H = 0.5*X-dX
    GH = (H*wx)@H.T
    edges = np.linspace(0, smax, int(smax/2)+1); us, ws = L.leggauss(24)
    s = np.concatenate([(a+b)/2+(b-a)/2*us for a, b in zip(edges[:-1], edges[1:])])
    ws = np.concatenate([(b-a)/2*ws for a, b in zip(edges[:-1], edges[1:])])
    m = np.real(digamma(0.25+0.5j*s))-np.log(np.pi)
    A = np.zeros((M, M))
    for k in range(0, len(s), 400):
        sk = s[k:k+400]; E = np.exp(1j*np.outer(x, sk)); Xh = (X*wx)@E*(0.5+1j*sk)
        A += np.real((Xh*(ws[k:k+400]*m[k:k+400]))@np.conj(Xh).T)/np.pi
    P = np.zeros((M, M))
    if with2 and np.log(2) < 2*T:
        a = np.log(2); uq, wq = L.leggauss(Nx); y = -T+(2*T-a)*(uq+1)/2; wy = (2*T-a)/2*wq
        X1, d1 = xi_d(y/T); X2, d2 = xi_d((y+a)/T)
        C = ((0.5*X1-d1)*wy)@(0.5*X2-d2).T; P = -V2*0.5*(C+C.T)
    cp = (X*wx)@np.exp(x/2)
    return A, P, GH, cp

def Cmat(T, M, e, Nx=400):
    C = np.zeros((M, M)); uq, wq = L.leggauss(Nx)
    for ak, wk, ek in zip(GA, GW, e):
        if ak >= 2*T: continue
        y = -T+(2*T-ak)*(uq+1)/2; wy = (2*T-ak)/2*wq
        def hb(t):
            u = t/T; V = np.array([L.legval(u, np.eye(M)[j]) for j in range(M)])
            dV = np.array([L.legval(u, L.legder(np.eye(M)[j])) for j in range(M)])
            b = (1-u**2)**2; db = -4*u*(1-u**2); return 0.5*V*b-(dV*b+V*db)/T
        c = (hb(y)*wy)@hb(y+ak).T; C += 2*wk*ek*0.5*(c+c.T)
    return C

def restrict(W, G, cp):
    Z = null_space(cp[None, :]); Wz = Z.T@W@Z; Gz = Z.T@G@Z
    d, U = np.linalg.eigh(Gz); k = d > 1e-13*d.max(); Q = U[:, k]/np.sqrt(d[k])
    return Q.T@Wz@Q

def main():
    M = int(sys.argv[1]) if len(sys.argv) > 1 else 24
    Ts = [float(t) for t in sys.argv[2].split(',')] if len(sys.argv) > 2 else \
         [0.5*np.log(2)+1e-9, 0.35, 0.36, 0.365, 0.37, 0.38, 0.40, 0.42, 0.45, 0.47, 0.48, 0.485, 0.49, 0.50, 0.52, 0.5*np.log(3)]
    print(f"M={M}.  lamA = min a_T|P_T ; D = lamA^inf - v2/2 (ruta directa) ; N = minSon_S - maxC_S (ruta semilocal por normas) ; L1 = ||eps_S||_L1(-2T,2T) (Young)")
    print("T       lamA     lamA^inf  D        | RS: minSon  maxC     N        rho*   | S: minSon  maxC     N        | sup|c_h(log2)|  L1")
    for T in Ts:
        A, P, GH, cp = build(T, M, True)
        ES = restrict(A+P, GH, cp); Ei = restrict(A, GH, cp)
        lS = eigh(ES, eigvals_only=True)[0]; li = eigh(Ei, eigvals_only=True)[0]
        row = f"{T:.4f} {lS:+.5f} {li:+.5f} {li-V2/2:+.5f} |"
        for g in ('RS', 'S'):
            CS = restrict(Cmat(T, M, GRIDS[g]), GH, cp); Son = ES+CS
            mS = eigh(Son, eigvals_only=True)[0]; cS = eigh(CS, eigvals_only=True)[-1]
            row += f" {mS:.5f} {cS:+.5f} {mS-cS:+.5f}"
            row += f" {eigh(CS, Son, eigvals_only=True)[-1]:+.4f} |" if g == 'RS' else " |"
        P2 = restrict(P, GH, cp)/(-V2) if np.log(2) < 2*T else np.zeros((1, 1))
        supc = np.abs(eigh(P2, eigvals_only=True)).max()
        m = GA <= 2*T; L1 = 2*np.sum(GW[m]*np.abs(GRIDS['RS'][m]))
        row += f" {supc:.4f}          {L1:.3f}"
        print(row, flush=True)

if __name__ == '__main__':
    main()
